import express from 'express';
import { createServer, Server } from 'node:http';
import { MockChatSource } from './twitch/mock.js';
import { config } from './config.js';
export interface State { hype: {score:number;baseline:number}; moments:unknown[]; translations:unknown[]; vote:unknown }
export function createApp(state:State, source:MockChatSource, mode=config.mode) {
  const app=express(); app.use(express.json({limit:'32kb'})); app.get('/overlay',(_req,res)=>res.sendFile(process.cwd()+'/public/overlay/index.html')); app.use('/overlay',express.static(process.cwd()+'/public/overlay'));
  const clients=new Set<express.Response>();
  app.get('/events',(_req,res)=>{res.set({'Content-Type':'text/event-stream','Cache-Control':'no-cache','Connection':'keep-alive'});res.flushHeaders();res.write(`event: state\ndata: ${JSON.stringify(state)}\n\n`);clients.add(res);_req.on('close',()=>clients.delete(res));});
  app.get('/state',(_req,res)=>res.json(state));
  app.post('/mock/chat',(req,res)=>{if(mode!=='mock')return res.status(404).json({error:'mock mode disabled'}); const {user,text,emotes,ts}=req.body??{};if(typeof user!=='string'||typeof text!=='string')return res.status(400).json({error:'user and text are required'});res.json(source.push({user,text,emotes,ts}));});
  return {app,emit:(event:string,data:unknown)=>{for(const client of clients)client.write(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`);}};
}
export function listen(app:express.Express,port:number):Promise<Server>{return new Promise(resolve=>{const server=createServer(app).listen(port,()=>resolve(server));});}
