import { AvailableClip, ClipResult, HelixClient } from './types.js';
export class TwitchHelix implements HelixClient {
  constructor(private clientId: string, private token: string, private broadcasterId: string, private botUserId: string) {}
  private async request(path: string, init: RequestInit = {}) {
    const response = await fetch(`https://api.twitch.tv/helix${path}`, { ...init, headers: { 'Client-Id': this.clientId, Authorization: `Bearer ${this.token}`, 'Content-Type': 'application/json', ...init.headers } });
    if (!response.ok) throw new Error(`Twitch Helix ${path}: ${response.status} ${await response.text()}`);
    return response.json() as Promise<any>;
  }
  async createMarker(desc: string) { const data = await this.request('/streams/markers', { method: 'POST', body: JSON.stringify({ user_id: this.broadcasterId, description: desc.slice(0, 140) }) }); return { id: data.data?.[0]?.id ?? '' }; }
  async createClip(): Promise<ClipResult> { const data = await this.request(`/clips?broadcaster_id=${encodeURIComponent(this.broadcasterId)}`, { method: 'POST' }); const clip = data.data?.[0]; if (!clip?.id) throw new Error('Twitch did not create a clip'); return { id: clip.id, editUrl: clip.edit_url ?? '' }; }
  async getClip(id: string): Promise<AvailableClip | null> { const data = await this.request(`/clips?id=${encodeURIComponent(id)}`); return data.data?.[0] ?? null; }
  async sendChatMessage(text: string) { await this.request('/chat/messages', { method: 'POST', body: JSON.stringify({ broadcaster_id: this.broadcasterId, sender_id: this.botUserId, message: text }) }); }
}
