export type Language = 'pcm' | 'yo' | 'fr' | 'es' | 'en' | 'unknown';
export function detectLanguage(text: string): { lang: Language; confidence: number } {
  const s = text.toLowerCase();
  const count = (words: string[]) => words.reduce((n, w) => n + (new RegExp(`\\b${w}\\b`, 'i').test(s) ? 1 : 0), 0);
  if (/[ẹọṣàèéìòù]/i.test(s)) return { lang: 'yo', confidence: 0.92 };
  const yo = count(['ẹ káàrọ̀', 'báwo', 'ẹ ṣé', 'mo fẹ́', 'ọmọ', 'ẹ jọ̀ọ́', 'ṣe']);
  if (yo >= 1) return { lang: 'yo', confidence: 0.78 };
  const pcm = count(['how far', 'wetin', 'abeg', 'wahala', 'e choke', 'i no fit', 'na wa', 'omo', 'dey', 'una', 'abi', 'sabi', 'sha']);
  if (pcm >= 1) return { lang: 'pcm', confidence: Math.min(0.95, 0.65 + pcm * 0.08) };
  const fr = count(['bonjour', 'merci', 'salut', 'ça', 'tous', 'beaucoup', 'bien', 'oui', 'pour', 'avec']);
  if (fr >= 1 || /[àâçéèêëîïôùûüÿœ]/i.test(s)) return { lang: 'fr', confidence: 0.72 };
  const es = count(['hola', 'gracias', 'buenos', 'estás', 'vamos', 'por', 'pero', 'muchas']);
  if (es >= 1 || /[¿¡ñ]/i.test(s)) return { lang: 'es', confidence: 0.72 };
  return { lang: /\b(the|and|you|this|is|are|hello|thanks)\b/i.test(s) ? 'en' : 'unknown', confidence: 0.55 };
}
