export interface TranslationProvider { readonly name: string; translate(text: string, source: string, target: string): Promise<{ translated: string; confidence: number } | null> }
export class LibreTranslateProvider implements TranslationProvider {
  readonly name = 'LibreTranslate';
  constructor(private url: string, private apiKey = '') {}
  async translate(text: string, source: string, target: string) {
    if (!this.url) return null;
    try { const r = await fetch(`${this.url.replace(/\/$/, '')}/translate`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ q: text, source: source === 'pcm' ? 'en' : source, target, format: 'text', ...(this.apiKey ? { api_key: this.apiKey } : {}) }) }); if (!r.ok) return null; const d = await r.json() as { translatedText?: string }; return d.translatedText ? { translated: d.translatedText, confidence: 0.7 } : null; } catch { return null; }
  }
}
export class NllbProvider implements TranslationProvider {
  readonly name = 'NLLB';
  constructor(private url: string) {}
  async translate(text: string, source: string, target: string) {
    if (!this.url || (source !== 'yo' && target !== 'yo')) return null;
    // Expected endpoint: POST {text, source_lang, target_lang} -> {translation}.
    try { const r = await fetch(this.url, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ text, source_lang: source, target_lang: target }) }); if (!r.ok) return null; const d = await r.json() as { translation?: string }; return d.translation ? { translated: d.translation, confidence: 0.55 } : null; } catch { return null; }
  }
}
export class OpenAIProvider implements TranslationProvider {
  readonly name = 'OpenAI';
  constructor(private enabled: boolean, private key: string) {}
  async translate(text: string, source: string, target: string) {
    if (!this.enabled || !this.key) return null;
    try { const r = await fetch('https://api.openai.com/v1/chat/completions', { method: 'POST', headers: { Authorization: `Bearer ${this.key}`, 'Content-Type': 'application/json' }, body: JSON.stringify({ model: 'gpt-4o-mini', messages: [{ role: 'system', content: `Translate from ${source} to ${target}. Return translation only.` }, { role: 'user', content: text }] }) }); if (!r.ok) return null; const d = await r.json() as any; const translation = d.choices?.[0]?.message?.content?.trim(); return translation ? { translated: translation, confidence: 0.7 } : null; } catch { return null; }
  }
}

