import phraseData from '../data/pidgin-phrases.json' with { type: 'json' };
import type { Language } from '../detect.js';

/** Translates known Pidgin and English phrases using the longest matching phrase. */
export class PidginPhraseProvider {
  private readonly phrases = Object.entries(phraseData).sort(
    ([left], [right]) => right.length - left.length,
  );

  supports(source: Language, target: string): boolean {
    return (
      (source === 'pcm' && target === 'en') ||
      (source === 'en' && target === 'pcm')
    );
  }

  translate(
    text: string,
    target: string,
  ): { translated: string; confidence: number } | null {
    if (target !== 'en' && target !== 'pcm') {
      return null;
    }

    const sourceText = target === 'en' ? text : this.reverse(text);
    const sourcePhrase = this.phrases.find(([phrase]) =>
      this.containsPhrase(sourceText, phrase),
    );

    if (!sourcePhrase) {
      return null;
    }

    const [pidgin, english] = sourcePhrase;
    const from = target === 'en' ? pidgin : english;
    const to = target === 'en' ? english : pidgin;
    const translated = sourceText.replace(
      new RegExp(`\\b${this.escapeRegExp(from)}\\b`, 'i'),
      to,
    );

    return {
      translated,
      confidence: 0.9,
    };
  }

  private reverse(text: string): string {
    const normalized = text.toLocaleLowerCase();
    const match = this.phrases.find(([, english]) =>
      this.containsPhrase(normalized, english),
    );

    if (!match) {
      return text;
    }

    const [pidgin, english] = match;
    return text.replace(
      new RegExp(`\\b${this.escapeRegExp(english)}\\b`, 'i'),
      pidgin,
    );
  }

  private containsPhrase(text: string, phrase: string): boolean {
    return new RegExp(`\\b${this.escapeRegExp(phrase)}\\b`, 'i').test(text);
  }

  private escapeRegExp(value: string): string {
    return value.replace(/[.*+?^${}()|[\\]\\]/g, '\\$&');
  }
}
/** Identifies common chat languages with small, explainable lexical heuristics. */
export type Language = 'pcm' | 'yo' | 'fr' | 'es' | 'en' | 'unknown';

const markers: Record<Exclude<Language, 'unknown'>, string[]> = {
  pcm: [
    'how far',
    'wetin',
    'abeg',
    'wahala',
    'e choke',
    'i no fit',
    'na wa',
    'omo',
    'dey',
    'una',
    'abi',
    'sabi',
    'sha',
  ],
  yo: ['ẹ káàrọ̀', 'báwo', 'ẹ ṣé', 'mo fẹ́', 'ọmọ', 'ẹ jọ̀ọ́', 'ṣe'],
  fr: [
    'bonjour',
    'merci',
    'salut',
    'ça',
    'tous',
    'beaucoup',
    'bien',
    'oui',
    'pour',
    'avec',
  ],
  es: ['hola', 'gracias', 'buenos', 'estás', 'vamos', 'por', 'pero', 'muchas'],
  en: ['the', 'and', 'you', 'this', 'is', 'are', 'hello', 'thanks'],
};

/** Returns the best supported language guess and an approximate confidence. */
export function detectLanguage(text: string): {
  lang: Language;
  confidence: number;
} {
  const normalized = text.toLocaleLowerCase();

  if (/[ẹọṣàèéìòù]/i.test(normalized)) {
    return { lang: 'yo', confidence: 0.92 };
  }

  const yorubaHits = countMarkers(normalized, markers.yo);
  if (yorubaHits > 0) {
    return { lang: 'yo', confidence: 0.78 };
  }

  const pidginHits = countMarkers(normalized, markers.pcm);
  if (pidginHits > 0) {
    return {
      lang: 'pcm',
      confidence: Math.min(0.95, 0.65 + pidginHits * 0.08),
    };
  }

  const frenchHits = countMarkers(normalized, markers.fr);
  if (frenchHits > 0 || /[àâçéèêëîïôùûüÿœ]/i.test(normalized)) {
    return { lang: 'fr', confidence: 0.72 };
  }

  const spanishHits = countMarkers(normalized, markers.es);
  if (spanishHits > 0 || /[¿¡ñ]/i.test(normalized)) {
    return { lang: 'es', confidence: 0.72 };
  }

  if (countMarkers(normalized, markers.en) > 0) {
    return { lang: 'en', confidence: 0.55 };
  }

  return { lang: 'unknown', confidence: 0.2 };
}

function countMarkers(text: string, words: string[]): number {
  return words.reduce((count, word) => {
    const expression = new RegExp(`\\b${escapeRegExp(word)}\\b`, 'i');
    return count + Number(expression.test(text));
  }, 0);
}

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\\]\\]/g, '\\$&');
}

